// isMetadataPath returns true if the path is a metadata directory that should be
// excluded from attribution calculations. These directories contain tool configuration
// and session data, not user code.
func isMetadataPath(path string) bool {
	return strings.HasPrefix(path, ".entire/") ||
		strings.HasPrefix(path, ".claude/")
}

